import{_ as e,c as r,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"使用條款","description":"在 Mac 上使用 qDiff 的簡要條款。","frontmatter":{"title":"使用條款","description":"在 Mac 上使用 qDiff 的簡要條款。"},"headers":[],"relativePath":"zh-TW/terms/index.md","filePath":"zh-TW/terms/index.md","lastUpdated":1793948370000}'),o={name:"zh-TW/terms/index.md"};function p(l,a,n,h,d,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="使用條款" tabindex="-1">使用條款 <a class="header-anchor" href="#使用條款" aria-label="Permalink to &quot;使用條款&quot;">​</a></h1><p><em>更新日期：2026 年 11 月 6 日</em></p><p>感謝使用 qDiff。以下條款適用於 App 和本網站。</p><h2 id="使用-app" tabindex="-1">使用 App <a class="header-anchor" href="#使用-app" aria-label="Permalink to &quot;使用 App&quot;">​</a></h2><p>qDiff 用於比較和整理你自己的檔案，家庭或工作場景都可以。你對自己選擇開啟的 檔案負責，重要資料請自行保留備份。</p><p>App 按現狀提供。我們努力讓它穩定可靠，但無法保證永不中斷或絕無差錯，也不對 資料遺失承擔責任。同步或刪除檔案之前，請先備份。</p><h2 id="免費版與購買" tabindex="-1">免費版與購買 <a class="header-anchor" href="#免費版與購買" aria-label="Permalink to &quot;免費版與購買&quot;">​</a></h2><p>所有比較功能免費。免費版在標籤列上顯示一個小標記；一次性購買可去掉它， 並包含以後新增的進階功能。沒有訂閱。</p><p>購買、退款與恢復購買由 Mac App Store 按 Apple 的條款和你的 Apple ID 處理， 我們不會收到你的付款資訊。</p><h2 id="你的內容" tabindex="-1">你的內容 <a class="header-anchor" href="#你的內容" aria-label="Permalink to &quot;你的內容&quot;">​</a></h2><p>我們不主張對你的檔案擁有任何權利，也不會收到這些檔案，詳見 <a href="./../privacy/">隱私政策</a>。</p><h2 id="本網站" tabindex="-1">本網站 <a class="header-anchor" href="#本網站" aria-label="Permalink to &quot;本網站&quot;">​</a></h2><p>網站內容僅供了解產品。隨著 qDiff 更新，功能描述可能會調整。</p><h2 id="變更" tabindex="-1">變更 <a class="header-anchor" href="#變更" aria-label="Permalink to &quot;變更&quot;">​</a></h2><p>條款如有更新，會修改上面的日期。更新後繼續使用 qDiff，即表示接受新條款。</p><h2 id="聯絡" tabindex="-1">聯絡 <a class="header-anchor" href="#聯絡" aria-label="Permalink to &quot;聯絡&quot;">​</a></h2><p>有疑問，寫信到 <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a>。</p>',17)])])}const m=e(o,[["render",p]]);export{f as __pageData,m as default};
